window.TADABBUR_QIYAMA = {"_meta":{"description":"تدبّر سورة القيامة (٧٥)، وسورةٌ مكّيّةٌ. محورُها تقريرُ البعثِ والقيامةِ والردُّ على منكري إعادةِ الخلق، ووصفُ أهوالِ يومِ القيامةِ وانقسامِ الوجوهِ إلى ناضرةٍ ناظرةٍ إلى ربّها وباسرةٍ خائفة، ومشهدِ الاحتضارِ حين تبلغ الروحُ التراقي، وذمِّ من كذّب وتولّى، وختامِها بالبرهانِ على البعثِ من خلقِ الإنسانِ من نطفة. وفيها معترضةٌ في أدبِ تلقّي الوحي «لا تحرك به لسانك لتعجل به». فيها «أيحسب الإنسان ألن نجمع عظامه»، و«وجوه يومئذ ناضرة إلى ربها ناظرة»، و«كلا إذا بلغت التراقي»، و«أيحسب الإنسان أن يترك سدى».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":75,"name":"القيامة","total_ayahs":40,"audio":["audio/075001.mp3","audio/075002.mp3","audio/075003.mp3","audio/075004.mp3","audio/075005.mp3","audio/075006.mp3","audio/075007.mp3","audio/075008.mp3","audio/075009.mp3","audio/075010.mp3"],"passages":[{"title":"القسمُ على البعثِ والردُّ على منكريه وأهوالُ القيامة","range":[1,15],"theme":"القسمُ بيومِ القيامةِ والنفسِ اللوّامة، والردُّ على منكرِ البعث «أيحسب الإنسان ألن نجمع عظامه بلى قادرين على أن نسوي بنانه»، وكشفِ باعثِه «بل يريد الإنسان ليفجر أمامه»، وأهوالِ القيامة «فإذا برق البصر وخسف القمر وجمع الشمس والقمر»، وطلبِ المفرّ «أين المفر كلا لا وزر إلى ربك يومئذ المستقر»، والإنباءِ بالأعمال «ينبأ الإنسان يومئذ بما قدم وأخر بل الإنسان على نفسه بصيرة»","verses":[{"n":1,"reflection":{"text":"«لا أقسم بيوم القيامة»: أُقسِم بيومِ القيامة (و«لا» لتأكيدِ القسمِ أو لنفيِ ما توهّموه من نفيِ البعث)؛ ففي هذا تعظيمُ يومِ القيامةِ بالقسمِ به على إثباتِ البعث؛ فعظّم يومَ القيامةِ وأيقن بوقوعه، فالقسمُ به توكيدٌ لحتمِ مجيئه، فاستعدّ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ يومِ القيامةِ واليقينُ بوقوعه."},"action":{"text":"تأمّل القسمَ بيومِ القيامة: لا أُقسِم بيومِ القيامة، أي أُقسِم بيومِ القيامة، و«لا» صلةٌ للتوكيدِ وتقويةِ القسم، أو ردٌّ لإنكارِ المكذّبين للبعثِ ثم ابتداءُ القسم؛ فأقسم الله بيومِ القيامةِ لعظمِ شأنه وهوله على إثباتِ البعثِ والجزاء «لا أقسم بيوم القيامة»؛ ففي هذا بيانُ تعظيمِ الله ليومِ القيامةِ بالقسمِ به، وتقريرِ وقوعه وحتمِ مجيئه، ردًّا على من أنكره؛ فيومُ القيامةِ عظيمٌ حقٌّ واقع؛ فعظّم أنت يومَ القيامةِ في قلبك، وأيقن بوقوعه يقينًا جازمًا، واستعدّ له بالإيمانِ والعمل؛ اقتربتِ الساعةُ وانشقّ القمر؛ إنّ الساعةَ آتيةٌ لا ريبَ فيها؛ يسألونك عن الساعةِ أيّان مرساها؛ فيومُ القيامةِ حقٌّ أقسم الله به لعظمِ شأنه؛ فعظّمه، وأيقن به، واستعدّ له؛ فمن أيقن بالقيامةِ استعدّ، ومن أنكرها أو غفل عنها خسر؛ فاجعل تعظيمَ يومِ القيامةِ واليقينَ بوقوعه دأبك."}},{"n":2,"reflection":{"text":"«ولا أقسم بالنفس اللوامة»، وأُقسِم بالنفسِ اللوّامةِ التي تلوم صاحبها على التقصيرِ والذنوبِ (نفسِ المؤمن)؛ ففي هذا تعظيمُ شأنِ النفسِ اللوّامةِ التي تحاسب نفسها؛ فلُم نفسك على تقصيرها وحاسبها، فلومُ النفسِ علامةُ إيمانها، فحاسب نفسك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محاسبةُ النفسِ ولومُها على التقصير."},"action":{"text":"تأمّل القسمَ بالنفسِ اللوّامة: ولا أُقسِم بالنفسِ اللوّامةِ، أي وأُقسِم بالنفسِ التي تلوم صاحبها وتؤنّبه على ما فرّط في جنبِ الله، وعلى الذنوبِ والتقصير، لا تثبت على حال؛ وهي نفسُ المؤمنِ التي تلوم نفسها في الدنيا على الشرِّ لِمَ فعلته وعلى الخيرِ لِمَ قصّرت فيه «ولا أقسم بالنفس اللوامة»؛ ففي هذا بيانُ تعظيمِ شأنِ النفسِ اللوّامةِ بالقسمِ بها، وأنها من علاماتِ الإيمانِ والخير، فإنّ لومَ النفسِ ومحاسبتَها دليلُ يقظتها وحياتها؛ فلومُ النفسِ ومحاسبتُها علامةُ إيمانٍ ورشد، بخلافِ النفسِ الأمّارةِ المطمئنّةِ إلى الشرّ؛ فحاسب أنت نفسك ولُمها على تقصيرها في الطاعةِ وعلى وقوعها في المعصية، ولا تُداهِنها؛ يا أيتها النفسُ المطمئنّة؛ وأمّا من خاف مقامَ ربّه ونهى النفسَ عن الهوى؛ حاسبوا أنفسكم قبل أن تُحاسَبوا؛ فمحاسبةُ النفسِ ولومُها على التقصيرِ سبيلُ إصلاحها؛ فلُمها، وحاسبها، ولا تُهمِلها؛ فمن حاسب نفسه ولامها استقام، ومن أهملها وسوّغ لها هلك؛ فاجعل محاسبةَ النفسِ ولومَها على التقصيرِ دأبك."}},{"n":3,"reflection":{"text":"«أيحسب الإنسان ألن نجمع عظامه»: أيظنّ الإنسانُ المنكرُ للبعثِ أن لن نجمع عظامه بعد تفرّقها وبلائها؟ ففي هذا إنكارٌ على من استبعد إعادةَ الخلق؛ فأيقن بقدرةِ الله على جمعِ عظامك وبعثك، فإنكارُ البعثِ سوءُ ظنٍّ بقدرةِ الله، فأيقن بها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بقدرةِ الله على البعثِ وجمعِ العظام."},"action":{"text":"تأمّل استنكارَ إنكارِ البعث: أيحسب الإنسانُ، أي أيظنّ الإنسانُ المكذّبُ بالبعث، ألن نجمع عظامه، أي أن لن نقدر على جمعِ عظامه بعد أن تفرّقت وبليت وصارت رميمًا؟ استفهامُ إنكارٍ وتوبيخٍ على استبعادهم البعث «أيحسب الإنسان ألن نجمع عظامه»؛ ففي هذا بيانُ الإنكارِ على من استبعد إعادةَ الخلقِ وجمعَ العظامِ بعد بلائها، وأنّ ذلك سوءُ ظنٍّ بقدرةِ الله؛ فقدرةُ الله على جمعِ العظامِ وإعادةِ الخلقِ لا تُستبعَد؛ فأيقن أنت بقدرةِ الله على بعثك وجمعِ عظامك مهما تفرّقت، فالذي خلقك أوّلًا قادرٌ على إعادتك؛ وضرب لنا مثلًا ونسي خلقه قال من يحيي العظامَ وهي رميم قل يحييها الذي أنشأها أوّلَ مرّة؛ زعم الذين كفروا أن لن يُبعَثوا قل بلى وربّي لتُبعَثنّ؛ أيحسب الإنسانُ أن يُترَك سدى؛ فقدرةُ الله على البعثِ وجمعِ العظامِ متحقّقة، وإنكارُها جهلٌ وسوءُ ظنّ؛ فأيقن بها، واستعدّ للبعث؛ فمن أيقن بالبعثِ استعدّ، ومن أنكره جهلًا خسر؛ فاجعل اليقينَ بقدرةِ الله على البعثِ دأبك."}},{"n":4,"reflection":{"text":"«بلى قادرين على أن نسوي بنانه»: بلى نجمعها، ونحن قادرون على أن نُسوّيَ بنانه (أطرافَ أصابعه بدقّةِ خطوطها)؛ ففي هذا بيانُ كمالِ قدرةِ الله حتى على إعادةِ أدقِّ التفاصيل؛ فأيقن بقدرةٍ تُعيد أطرافَ أصابعك بدقّتها، فقدرةُ الله تبلغ أدقَّ الخلق، فأيقن بها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بكمالِ قدرةِ الله على أدقِّ الخلق."},"action":{"text":"تأمّل كمالَ القدرة: بلى، أي بلى نجمع عظامه ونعيده، قادرين على أن نُسوّيَ بنانه، أي بل نحن قادرون على ما هو أدقُّ من جمعِ العظام: أن نُسوّيَ بنانه، أي نُعيد أطرافَ أصابعه بخطوطها ودقائقها على ما كانت، أو نجعلها مستويةً كخفِّ البعيرِ لو شئنا؛ فقدرتُنا تبلغ أدقَّ التفاصيل «بلى قادرين على أن نسوي بنانه»؛ ففي هذا بيانُ كمالِ قدرةِ الله، وأنه لا يقتصر على جمعِ العظامِ الكبار، بل يُعيد أدقَّ الأجزاءِ وألطفَها كأطرافِ الأصابعِ بخطوطها المتمايزة؛ فقدرةُ الله تامّةٌ تبلغ أدقَّ الخلق؛ فأيقن أنت بكمالِ قدرةِ الله على بعثك وإعادتك بأدقِّ تفاصيلك، فمن قدر على البنانِ فهو على ما سواه أقدر؛ وفي أنفسكم أفلا تبصرون؛ لخلقُ السماواتِ والأرضِ أكبرُ من خلقِ الناس؛ ما خلقكم ولا بعثكم إلا كنفسٍ واحدة؛ فقدرةُ الله تبلغ أدقَّ الخلقِ فضلًا عن جُمَلِه؛ فأيقن بها، واستعدّ للبعث؛ فمن أيقن بكمالِ قدرةِ الله آمن بالبعث، ومن جهلها أنكره؛ فاجعل اليقينَ بكمالِ قدرةِ الله على أدقِّ الخلقِ دأبك."}},{"n":5,"reflection":{"text":"«بل يريد الإنسان ليفجر أمامه»: بل يريد الإنسانُ أن يستمرّ في الفجورِ والمعصيةِ فيما يستقبل من عمره (لا شكٌّ في البعثِ حقيقةً)؛ ففي هذا بيانُ أنّ إنكارَ البعثِ ذريعةٌ لإطلاقِ الشهواتِ لا شبهةٌ عقليّة؛ فاحذر أن يحملك هوى المعصيةِ على التكذيبِ بالبعث، فالفجورُ يدفع لإنكارِ الآخرة، فطهّر قصدك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن يحمل الهوى على تكذيبِ البعث، وإصلاحُ القصد."},"action":{"text":"تأمّل الباعثَ الخفيّ للإنكار: بل يريد الإنسانُ ليفجر أمامه، أي ليس إنكارُه للبعثِ عن شبهةٍ حقيقيّة، بل يريد أن يمضيَ قُدُمًا في الفجورِ والمعاصي فيما يستقبل من عمره، ويؤخّر التوبةَ ويكذّب بالبعثِ ليُطلِق لنفسه العنانَ في الشهوات؛ فالحاملُ له على التكذيبِ إرادةُ الفجورِ لا الشكّ «بل يريد الإنسان ليفجر أمامه»؛ ففي هذا بيانُ أنّ إنكارَ كثيرٍ من الناسِ للبعثِ ليس عن دليلٍ أو شبهةٍ عقليّة، بل هو ذريعةٌ لإطلاقِ الشهواتِ والاستمرارِ في المعصيةِ وتسويفِ التوبة؛ فالهوى يحمل على تكذيبِ الحقِّ لا العقل؛ فاحذر أنت أن يحملك حبُّ المعصيةِ وإرادةُ الفجورِ على التهاونِ بالبعثِ أو تكذيبه، وأصلِح قصدك ونيّتك، فإنّ التكذيبَ كثيرًا ما يكون تبعًا للهوى؛ أرأيت من اتّخذ إلهه هواه؛ ويريدون أن يتّخذوا بين ذلك سبيلًا؛ فبل ظننتم أن لن يبعث الله أحدًا؛ فإرادةُ الفجورِ تحمل على تكذيبِ البعث، وإصلاحُ القصدِ يحمل على الإيمانِ به؛ فطهّر قصدك، واحذر الهوى، وأيقن بالبعث؛ فمن أصلح قصده آمن، ومن اتّبع هواه كذّب؛ فاجعل الحذرَ من أن يحمل الهوى على تكذيبِ البعثِ دأبك."}},{"n":6,"reflection":{"text":"«يسأل أيان يوم القيامة»: يسأل هذا الإنسانُ استبعادًا واستهزاءً: متى يومُ القيامة؟ ففي هذا بيانُ سؤالِ المكذّبِ عن وقتِ القيامةِ تعنّتًا لا استرشادًا؛ فلا تسأل عن وقتِ القيامةِ متعنّتًا، بل استعدّ لها في كلِّ حين، فالسؤالُ عن وقتها استبعادٌ، والواجبُ الاستعداد، فاستعدّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للقيامةِ في كلِّ حين، وتركُ التعنّتِ في وقتها."},"action":{"text":"تأمّل سؤالَه الاستبعاديّ: يسأل، أي يسأل هذا الإنسانُ المكذّبُ المريدُ للفجور، أيّان يومُ القيامة، أي متى يكون يومُ القيامة؟ سؤالَ استبعادٍ وتكذيبٍ واستهزاءٍ لا سؤالَ استرشادٍ واسترشاد؛ فيستبعد وقوعه ويستبطئه تكذيبًا «يسأل أيان يوم القيامة»؛ ففي هذا بيانُ أنّ المكذّبَ يسأل عن وقتِ القيامةِ على وجهِ الاستبعادِ والتعنّتِ والاستهزاء، لا على وجهِ الاسترشادِ والاستعداد؛ فالسؤالُ عن وقتها تعنّتًا من علاماتِ التكذيب؛ فلا تسأل أنت عن وقتِ القيامةِ متعنّتًا مستبعدًا، فإنّ علمها عند الله وحده، بل استعدّ لها في كلِّ حينٍ كأنها قريبة، فما ينفعك معرفةُ وقتها بل الاستعدادُ لها؛ يسألونك عن الساعةِ أيّان مرساها قل إنما علمها عند ربّي؛ إنّ الله عنده علمُ الساعة؛ اقتربت الساعةُ؛ فالواجبُ الاستعدادُ للقيامةِ لا التنقيبُ عن وقتها؛ فاستعدّ لها دائمًا، ولا تسأل متعنّتًا، ولا تستبعد وقوعها؛ فمن استعدّ للقيامةِ نجا، ومن شُغِل بوقتها متعنّتًا خسر؛ فاجعل الاستعدادَ للقيامةِ في كلِّ حينٍ دأبك."}},{"n":7,"reflection":{"text":"«فإذا برق البصر»: فإذا شخص البصرُ وحار وتحيّر من هولِ ما يرى يومَ القيامة؛ ففي هذا بيانُ شدّةِ هولِ القيامةِ حتى تبرق الأبصار؛ فاستعدّ ليومٍ تحار فيه الأبصارُ من الهول، فأهوالُ القيامةِ تُبهِر الأبصار، فاستعدّ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ هولِ القيامةِ الذي تحار منه الأبصار."},"action":{"text":"تأمّل هولَ ذلك اليوم: فإذا برق البصرُ، أي فإذا شخص البصرُ وحار وتحيّر وبهت من شدّةِ هولِ ما يرى يومَ القيامةِ من الأهوال، فلا يطرف ولا يستقرّ من الفزع «فإذا برق البصر»؛ ففي هذا بيانُ شدّةِ هولِ يومِ القيامة، حتى تبرق الأبصارُ وتشخص وتتحيّر من عظمِ ما تراه من الأهوال؛ فأهوالُ القيامةِ تبهر الأبصارَ وتحيّرها؛ فاستعدّ أنت ليومٍ تبرق فيه الأبصارُ وتشخص من الهول، بالإيمانِ والعملِ الصالحِ الذي يؤمّنك من فزعه؛ إنما يؤخّرهم ليومٍ تشخص فيه الأبصار؛ لا يرتدّ إليهم طرفهم وأفئدتهم هواء؛ يوم ترونها تذهل كلُّ مرضعةٍ عمّا أرضعت؛ فأهوالُ القيامةِ تبرق منها الأبصار، والاستعدادُ لها بالعمل؛ فاستحضر هولها، واستعدّ لها، واعمل لتأمن فزعها؛ فمن استعدّ لها أمِن، ومن غفل عنها فوجئ بهولها؛ فاجعل استحضارَ هولِ القيامةِ دأبك."}},{"n":8,"reflection":{"text":"«وخسف القمر»، وذهب ضوءُ القمرِ وزال نورُه وأظلم؛ ففي هذا بيانُ اختلالِ نظامِ الكونِ يومَ القيامة؛ فاعتبر بزوالِ نورِ القمرِ الثابتِ آيةً على انقضاءِ الدنيا، فما يُظنّ ثباته يزول، فاستعدّ لذلك اليوم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بزوالِ نظامِ الكونِ والاستعدادُ ليومِ القيامة."},"action":{"text":"تأمّل خسوفَ القمر: وخسف القمرُ، أي ذهب ضوءُ القمرِ وزال نوره بالكلّيّةِ وأظلم، وانطمس بريقه يومَ القيامة «وخسف القمر»؛ ففي هذا بيانُ اختلالِ نظامِ الكونِ وزوالِ أنوارِ الأجرامِ العظيمةِ يومَ القيامة، فالقمرُ الذي كان آيةً منيرةً يُخسَف ويُظلِم؛ فما يُظنّ ثباتُه من نظامِ الكونِ يزول ويختلّ يومَ القيامة؛ فاعتبر أنت بزوالِ نورِ القمرِ الثابتِ آيةً على انقضاءِ الدنيا وقربِ الآخرة، واستعدّ لذلك اليوم؛ إذا الشمسُ كُوِّرت وإذا النجومُ انكدرت؛ فإذا برق البصرُ وخسف القمرُ وجُمِع الشمسُ والقمر؛ إذا السماءُ انفطرت وإذا الكواكبُ انتثرت؛ فنظامُ الكونِ الثابتُ يختلّ يومَ القيامةِ إيذانًا بعظمِ ذلك اليوم؛ فاعتبر، واستعدّ، ولا تغترّ بثباتِ الدنيا؛ فمن اعتبر واستعدّ نجا، ومن اغترّ بثباتِ الدنيا غفل؛ فاجعل الاعتبارَ بزوالِ نظامِ الكونِ والاستعدادَ للقيامةِ دأبك."}},{"n":9,"reflection":{"text":"«وجمع الشمس والقمر»، وجُمِع بين الشمسِ والقمرِ في ذهابِ الضوءِ (أو قُرِن بينهما مكوَّرين مظلمين)؛ ففي هذا بيانُ عظمِ التغييرِ الكونيِّ يومَ القيامة؛ فاعتبر بجمعِ النيّرين اللذين لا يجتمعان، آيةً على قدرةِ الله وهولِ اليوم، فاستعدّ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعظمِ التغييرِ الكونيِّ يومَ القيامةِ والاستعدادُ له."},"action":{"text":"تأمّل جمعَ النيّرين: وجُمِع الشمسُ والقمرُ، أي جُمِع بينهما في ذهابِ الضوءِ وزوالِ النور، فيُكوَّران ويُقرَن بينهما مظلمين مسلوبَي النور، بعد أن كانا آيتين للنهارِ والليل، وقيل: يُجمَعان فيُقذَفان في النار «وجمع الشمس والقمر»؛ ففي هذا بيانُ عظمِ التغييرِ الكونيِّ يومَ القيامة، إذ يُجمَع بين الشمسِ والقمرِ اللذين لا يجتمعان في الدنيا، في ذهابِ نورهما، دلالةً على قدرةِ الله وهولِ ذلك اليوم؛ فقدرةُ الله تُغيّر أعظمَ النظمِ الكونيّة؛ فاعتبر أنت بجمعِ الشمسِ والقمرِ آيةً على قدرةِ الله وعلى هولِ يومِ القيامة، واستعدّ له بالعمل؛ لا الشمسُ ينبغي لها أن تُدرِك القمرَ ولا الليلُ سابقُ النهار (في الدنيا)؛ وإذا الشمسُ كُوِّرت؛ فجمعُ النيّرين يومَ القيامةِ آيةٌ على القدرةِ وهولِ اليوم؛ فاعتبر، واستعدّ، وأيقن بقدرةِ الله؛ فمن اعتبر واستعدّ نجا، ومن غفل خسر؛ فاجعل الاعتبارَ بعظمِ التغييرِ الكونيِّ والاستعدادَ للقيامةِ دأبك."}},{"n":10,"reflection":{"text":"«يقول الإنسان يومئذ أين المفر»: يقول الإنسانُ يومئذٍ من شدّةِ الهول: أين المهربُ والمفرّ من العذاب؟ ففي هذا بيانُ فزعِ الإنسانِ يومَ القيامةِ وطلبِه المهربَ حيث لا مهرب؛ فاطلب المفرَّ اليومَ بالتوبةِ والعمل قبل يومٍ لا مفرَّ فيه، فلا مهربَ يومئذٍ إلا بما قدّمت، فبادر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ النجاةِ اليومَ بالعملِ قبل يومٍ لا مفرَّ فيه."},"action":{"text":"تأمّل فزعَ الإنسان: يقول الإنسانُ يومئذٍ، أي يومَ القيامةِ عند رؤيةِ تلك الأهوال، أين المفرّ، أي أين المهربُ والملجأُ والمنجى من العذابِ وأهوالِ ذلك اليوم؟ يطلب مفرًّا يفرّ إليه فزعًا، فلا يجد «يقول الإنسان يومئذ أين المفر»؛ ففي هذا بيانُ شدّةِ فزعِ الإنسانِ يومَ القيامةِ حتى يطلب المهربَ من العذاب، ولا مهربَ ولا مفرَّ يومئذٍ؛ فلا فرارَ يومَ القيامةِ من عذابِ الله؛ فاطلب أنت المفرَّ والنجاةَ اليومَ في الدنيا بالتوبةِ والإيمانِ والعملِ الصالح، قبل يومٍ لا ينفع فيه فرار؛ يوم يفرّ المرءُ من أخيه؛ ففروا إلى الله؛ يقول الإنسانُ يومئذٍ أين المفرّ كلّا لا وزر؛ فلا مفرَّ يومَ القيامةِ إلا ما قدّمت من عمل؛ فبادر بالنجاةِ اليوم، واعمل، وتب، ولا تسوّف؛ فمن طلب النجاةَ اليومَ بالعملِ نجا، ومن سوّف حتى القيامةِ لم يجد مفرًّا؛ فاجعل طلبَ النجاةِ اليومَ بالعملِ دأبك."}},{"n":11,"reflection":{"text":"«كلا لا وزر»: حقًّا، لا ملجأَ ولا حصنَ ولا مَعقِلَ يُعتصَم به من الله يومئذٍ؛ ففي هذا بيانُ انقطاعِ كلِّ ملجأٍ سوى الله يومَ القيامة؛ فالجأ إلى الله وحده اليومَ فلا ملجأَ منه إلا إليه، فلا وزرَ يومئذٍ إلا العملُ الصالح، فالجأ إليه واعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الالتجاءُ إلى الله وحده، والعلمُ بأن لا ملجأَ سواه."},"action":{"text":"تأمّل انقطاعَ الملاجئ: كلّا، أي حقًّا، ردعًا لمن يطلب المفرّ، لا وزرَ، أي لا ملجأَ ولا مَعقِلَ ولا حصنَ ولا جبلَ يُعتصَم به ويُتحصَّن فيه من أمرِ الله وعذابه يومئذٍ، فقد انقطعت الملاجئُ كلُّها إلا الله «كلا لا وزر»؛ ففي هذا بيانُ أنه لا ملجأَ يومَ القيامةِ من الله ولا مهربَ ولا مَعقِل، فقد انقطعت الأسبابُ والوسائلُ التي كان يُعتصَم بها في الدنيا؛ فلا ملجأَ يومَ القيامةِ من الله إلا إليه؛ فالجأ أنت إلى الله وحده اليومَ بالإيمانِ والتوبةِ والعمل، فإنه لا مَعقِلَ منه إلا إليه، ولا وزرَ يومئذٍ إلا العملُ الصالحُ الذي قدّمته؛ ما لكم من ملجإٍ يومئذٍ وما لكم من نكير؛ يقولون أين المفرّ * كلّا لا وزر؛ ففروا إلى الله؛ فلا ملجأَ من الله يومَ القيامةِ إلا إليه، ولا نجاةَ إلا بالعمل؛ فالجأ إليه اليوم، واعمل، ولا تعتصم بغيره؛ فمن الجأ إلى الله وعمل نجا، ومن اعتصم بغيره خُذِل؛ فاجعل الالتجاءَ إلى الله وحده والعلمَ بأن لا ملجأَ سواه دأبك."}},{"n":12,"reflection":{"text":"«إلى ربك يومئذ المستقر»: إلى ربّك وحده يومئذٍ المستقرُّ والمرجعُ والمصير، إليه ينتهي الخلقُ للحساب؛ ففي هذا بيانُ أنّ المرجعَ إلى الله وحده يومَ القيامة؛ فاستحضر أنّ مصيرك إلى الله، فاعمل لِما بعد الرجوعِ إليه، فالمستقرُّ إلى ربّك فأعدّ للقائه، فاعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ الرجوعِ إلى الله والعملُ للقائه."},"action":{"text":"تأمّل المرجعَ إلى الله: إلى ربّك يومئذٍ المستقرُّ، أي إلى ربّك وحده يومَ القيامةِ منتهى الخلقِ ومصيرهم ومستقرّهم، إليه يرجعون وعنده يستقرّون للحسابِ والجزاء، فلا مستقرَّ ولا مرجعَ إلا إليه «إلى ربك يومئذ المستقر»؛ ففي هذا بيانُ أنّ مرجعَ الخلقِ ومصيرهم ومستقرَّهم يومَ القيامةِ إلى الله وحده، إليه يُساقون وعنده يُحاسَبون ويستقرّون في جنّةٍ أو نار؛ فالمصيرُ إلى الله وحده، وهو المستقرُّ الأخير؛ فاستحضر أنت أنّ مرجعك ومصيرك إلى الله، واعمل لِما بعد الرجوعِ إليه، وأعدّ للقائه ما يُنجيك؛ وأنّ إلى ربّك المنتهى؛ إنّ إلينا إيابهم ثمّ إنّ علينا حسابهم؛ يومئذٍ تُعرَضون لا تخفى منكم خافية؛ فالمرجعُ إلى الله، والمستقرُّ عنده، فالعاقلُ من أعدّ للقائه؛ فاستحضر الرجوعَ إليه، واعمل للقائه، وأعدّ العدّة؛ فمن أعدّ للقاءِ الله نجا، ومن غفل عن مصيره خسر؛ فاجعل استحضارَ الرجوعِ إلى الله والعملَ للقائه دأبك."}},{"n":13,"reflection":{"text":"«ينبأ الإنسان يومئذ بما قدم وأخر»: يُخبَر الإنسانُ يومئذٍ بجميعِ أعماله: ما قدّم منها وما أخّر، وما أسلف وما خلّف من أثر؛ ففي هذا بيانُ إحصاءِ الأعمالِ كلِّها والإنباءِ بها يومَ القيامة؛ فراقب عملك فكلُّه محصًى ستُنبَّأ به، فما قدّمت وأخّرت محسوب، فأحسِن عملك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ العملِ واستحضارُ الإنباءِ بكلِّ ما قدّم وأخّر."},"action":{"text":"تأمّل الإنباءَ بالأعمال: يُنبَّأ الإنسانُ يومئذٍ، أي يُخبَر ويُبصَّر يومَ القيامةِ، بما قدّم وأخّر، أي بجميعِ أعماله: ما قدّمه من عملٍ صالحٍ أو سيّئٍ في حياته، وما أخّره فجرى بعد موته من سنّةٍ حسنةٍ أو سيّئةٍ وأثرٍ باقٍ، وما قدّم من طاعةٍ وأخّر من تفريط؛ فيُحاط بعمله كلِّه فيُنبَّأ به «ينبأ الإنسان يومئذ بما قدم وأخر»؛ ففي هذا بيانُ أنّ أعمالَ الإنسانِ كلَّها محصاةٌ محفوظة، وأنه يُخبَر بها يومَ القيامةِ ما تقدّم منها وما تأخّر، ما أسلف وما خلّف من آثار؛ فالأعمالُ كلُّها محصاةٌ لا يُغادَر منها شيء؛ فراقب أنت عملك وأثرك، واعلم أنّ كلَّ ما تقدّمه أو تُخلِّفه من أثرٍ محسوبٌ ستُنبَّأ به، فأحسِن ما تقدّم وما تُخلّف؛ يومئذٍ يصدر الناسُ أشتاتًا ليُرَوا أعمالهم؛ ونكتب ما قدّموا وآثارهم؛ ووجدوا ما عملوا حاضرًا؛ فأعمالُ العبدِ وآثارُه كلُّها محصاةٌ يُنبَّأ بها؛ فراقب عملك، وأحسِن ما تقدّم وما تُخلّف، واستحضر الإحصاء؛ فمن راقب عمله وأحسنه سُرّ يومَ الإنباء، ومن أهمله ندم؛ فاجعل مراقبةَ العملِ واستحضارَ الإنباءِ به دأبك."}},{"n":14,"reflection":{"text":"«بل الإنسان على نفسه بصيرة»: بل الإنسانُ على نفسه شاهدٌ بصيرٌ بعمله، يعلم ما فعل وإن أنكر؛ ففي هذا بيانُ أنّ الإنسانَ شاهدٌ على نفسه لا يخفى عليه حالها؛ فحاسب نفسك فأنت أعلمُ بها، فالنفسُ شاهدةٌ على صاحبها، فاصدق مع نفسك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصدقُ مع النفسِ ومحاسبتُها، والعلمُ بأنها شاهدةٌ على صاحبها."},"action":{"text":"تأمّل شهادةَ الإنسانِ على نفسه: بل الإنسانُ على نفسه بصيرةٌ، أي بل هو شاهدٌ على نفسه بصيرٌ بعمله، يعلم ما عمل من خيرٍ أو شرّ، فجوارحُه تشهد عليه، وهو أعلمُ بحقيقةِ حاله وإن أنكر بلسانه؛ فالإنسانُ حجّةٌ على نفسه بعمله «بل الإنسان على نفسه بصيرة»؛ ففي هذا بيانُ أنّ الإنسانَ شاهدٌ على نفسه بصيرٌ بعمله، يعلم في قرارةِ نفسه ما قدّم وإن جادل واعتذر، فلا تخفى عليه حقيقةُ حاله؛ فالنفسُ شاهدةٌ على صاحبها بما عملت؛ فاصدق أنت مع نفسك وحاسبها، فأنت أعلمُ الناسِ بها وبعملها، ولا تخادعها ولا تُبرِّرها؛ اقرأ كتابك كفى بنفسك اليوم عليك حسيبًا؛ يوم تشهد عليهم ألسنتهم وأيديهم وأرجلهم بما كانوا يعملون؛ بل الإنسانُ على نفسه بصيرة؛ فالإنسانُ بصيرٌ بنفسه شاهدٌ عليها؛ فاصدق معها، وحاسبها، ولا تخادعها؛ فمن صدق مع نفسه وحاسبها أصلحها، ومن خادعها وبرّرها أهلكها؛ فاجعل الصدقَ مع النفسِ ومحاسبتَها دأبك."}},{"n":15,"reflection":{"text":"«ولو ألقى معاذيره»، ولو ألقى الإنسانُ معاذيرَه واعتذاراته (فلن تنفعه لأنه شاهدٌ على نفسه)؛ ففي هذا بيانُ أنّ الاعتذاراتِ الباطلةَ لا تنفع يومَ القيامة؛ فلا تعتذر بالباطلِ فلن ينفعك، بل بادر بالتوبةِ الصادقة، فالمعاذيرُ لا تنفع مع علمِ النفس، فاصدق واعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ الاعتذارِ بالباطل، والمبادرةُ بالتوبةِ الصادقة."},"action":{"text":"تأمّل عدمَ نفعِ المعاذير: ولو ألقى معاذيره، أي ولو اعتذر الإنسانُ عن نفسه وجادل عنها وألقى حُججه وأعذاره الباطلة، فلن تنفعه تلك المعاذير، لأنه شاهدٌ على نفسه يعلم كذبها، وجوارحُه تشهد عليه؛ فالاعتذارُ بالباطلِ لا يدفع عنه شيئًا «ولو ألقى معاذيره»؛ ففي هذا بيانُ أنّ اعتذاراتِ الإنسانِ الباطلةَ يومَ القيامةِ لا تنفعه، لأنه بصيرٌ بنفسه، والحقُّ ظاهرٌ عليه؛ فالمعاذيرُ الكاذبةُ لا تنفع مع علمِ النفسِ وشهادةِ الجوارح؛ فلا تعتذر أنت بالباطلِ ولا تُبرِّر معاصيك، فإنّ ذلك لا ينفعك يومَ القيامة، بل بادر بالتوبةِ الصادقةِ والعملِ الصالح، فهو الذي ينفع؛ يوم لا ينفع الظالمين معذرتهم؛ فيومئذٍ لا ينفع الذين ظلموا معذرتهم ولا هم يُستعتَبون؛ ولا يُؤذَن لهم فيعتذرون؛ فالاعتذارُ بالباطلِ لا ينفع، والتوبةُ الصادقةُ هي النافعة؛ فاترك المعاذيرَ الكاذبة، وبادر بالتوبةِ والعمل؛ فمن تاب وعمل نفعه ذلك، ومن اعتذر بالباطلِ لم ينفعه؛ فاجعل تركَ الاعتذارِ بالباطلِ والمبادرةَ بالتوبةِ دأبك."}}]},{"title":"أدبُ تلقّي الوحي ثم بيانُ إيثارِ العاجلة","range":[16,20],"theme":"معترضةٌ في أدبِ تلقّي الوحي «لا تحرك به لسانك لتعجل به إن علينا جمعه وقرآنه فإذا قرأناه فاتبع قرآنه ثم إن علينا بيانه»، ثم ذمِّ إيثارِ الدنيا «كلا بل تحبون العاجلة»","verses":[{"n":16,"reflection":{"text":"«لا تحرك به لسانك لتعجل به»: لا تحرّك، يا محمد، لسانك بالقرآنِ عند نزولِه لتعجل بأخذه خشيةَ أن يتفلّت؛ ففي هذا بيانُ أدبِ تلقّي الوحي بالتؤدةِ والإنصات؛ فأنصت لكلامِ الله ولا تعجل، فالعجلةُ تُفوِّت الفهم، فتؤدة وإنصات، فأنصت لكلامه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التؤدةُ والإنصاتُ عند تلقّي كلامِ الله، وتركُ العجلة."},"action":{"text":"تأمّل أدبَ تلقّي الوحي: لا تحرّك به لسانك، أي لا تحرّك، يا محمد، لسانك بالقرآنِ أثناء نزولِ الوحي، لتعجل به، أي لتأخذه وتحفظه بسرعةٍ خشيةَ أن ينفلت منك؛ فنُهِيَ ﷺ عن العجلةِ في تلقّي الوحيِ قبل فراغِ جبريلَ منه؛ وهذه معترضةٌ في أثناءِ ذكرِ القيامةِ تعليمًا لأدبِ التلقّي «لا تحرك به لسانك لتعجل به»؛ ففي هذا بيانُ أدبِ تلقّي الوحي: التؤدةُ والإنصاتُ وتركُ العجلةِ والاكتفاءُ بضمانِ الله بحفظه؛ فالعجلةُ في التلقّي تُفوِّت الفهمَ والطمأنينة؛ فتأدّب أنت في تلقّي كلامِ الله والعلمِ عمومًا بالتؤدةِ والإنصاتِ وحضورِ القلب، ولا تعجل قبل تمامِ الاستماع؛ ولا تعجل بالقرآنِ من قبلِ أن يُقضى إليك وحيه وقل ربِّ زدني علمًا؛ وقرآنًا فرقناه لتقرأه على الناسِ على مكث؛ فالتؤدةُ في تلقّي الوحيِ والعلمِ أدبٌ نبويّ، والعجلةُ تُفوِّت المقصود؛ فأنصت، وتأنَّ، ولا تعجل؛ فمن تلقّى بتؤدةٍ فهم وثبت، ومن عجل فاته الفهم؛ فاجعل التؤدةَ والإنصاتَ عند تلقّي كلامِ الله دأبك."}},{"n":17,"reflection":{"text":"«إن علينا جمعه وقرآنه»: إنّ علينا، نحن، جمعَ القرآنِ في صدرك وتثبيتَه، وقراءتَه بلسانك؛ ففي هذا بيانُ تكفّلِ الله بحفظِ القرآنِ في صدرِ نبيّه؛ فثِق بضمانِ الله لحفظِ كلامه، فالله متكفّلٌ بجمعِ القرآنِ وحفظه، فاطمئنّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بضمانِ الله لحفظِ القرآنِ والاطمئنانُ إليه."},"action":{"text":"تأمّل ضمانَ الله: إنّ علينا جمعه، أي إنّ علينا نحن أن نجمعه في صدرك ونثبّته في قلبك فلا يذهب عليك منه شيء، وقرآنه، أي وأن نُثبِت قراءتَه على لسانك، فلا تخف فوته «إن علينا جمعه وقرآنه»؛ ففي هذا بيانُ أنّ الله تكفّل بجمعِ القرآنِ في صدرِ نبيّه ﷺ وتثبيتِه وقراءته، فلا حاجةَ به إلى العجلةِ خشيةَ النسيان، فإنّ الحافظَ له هو الله؛ فالله متكفّلٌ بحفظِ القرآن؛ فثِق أنت بضمانِ الله لحفظِ كلامه، واطمئنّ إلى أنّ القرآنَ محفوظٌ بحفظِ الله لا يضيع ولا يُبدَّل، وتلقَّه بطمأنينةٍ لا بعجلة؛ سنقرئك فلا تنسى؛ إنا نحن نزّلنا الذكرَ وإنا له لحافظون؛ لا يأتيه الباطلُ من بين يديه ولا من خلفه؛ فحفظُ القرآنِ مضمونٌ بضمانِ الله، فالطمأنينةُ إليه واجبة؛ فثِق بضمانه، واطمئنّ، وتلقَّ بتؤدة؛ فمن وثق بحفظِ الله للقرآنِ اطمأن، ومن عجل خوفًا قصّر في الأدب؛ فاجعل الثقةَ بضمانِ الله لحفظِ القرآنِ دأبك."}},{"n":18,"reflection":{"text":"«فإذا قرأناه فاتبع قرآنه»: فإذا قرأه عليك جبريلُ عنّا فاستمع له واتّبع قراءته (ثم اقرأه بعده)؛ ففي هذا بيانُ أدبِ الإنصاتِ للوحي ثم اتّباعه؛ فأنصت لكلامِ الله ثم اتّبعه علمًا وعملًا، فالإنصاتُ ثم الاتّباعُ سبيلُ الانتفاع، فأنصت واتّبع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإنصاتُ لكلامِ الله ثم اتّباعُه علمًا وعملًا."},"action":{"text":"تأمّل أمرَ الاتّباع: فإذا قرأناه، أي فإذا قرأه عليك جبريلُ عنّا وفرغ من قراءته، فاتّبع قرآنه، أي فاستمع لقراءته وأنصت لها حتى يُتمّها، ثم اتّبعها بأن تقرأه بعده كما أقرأك، وتتّبع ما فيه من الأمرِ والنهي «فإذا قرأناه فاتبع قرآنه»؛ ففي هذا بيانُ أدبِ تلقّي الوحي: الإنصاتُ لقراءته حتى تتمّ، ثم اتّباعها بالقراءةِ والفهمِ والعمل؛ فالإنصاتُ أوّلًا ثم الاتّباعُ سبيلُ الانتفاعِ بكلامِ الله؛ فأنصت أنت لكلامِ الله إذا تُلِيَ، ثم اتّبعه: تلاوةً وفهمًا وعملًا بما فيه، فلا يكفي السماعُ دون الاتّباع؛ وإذا قُرِئ القرآنُ فاستمعوا له وأنصتوا لعلّكم تُرحَمون؛ الذين يستمعون القولَ فيتّبعون أحسنه؛ فاتّبعوه واتّقوا؛ فالإنصاتُ لكلامِ الله ثم اتّباعُه علمًا وعملًا سبيلُ الرحمةِ والهدى؛ فأنصت، ثم اتّبع، واعمل بما فيه؛ فمن أنصت واتّبع انتفع، ومن سمع ولم يتّبع حُرِم؛ فاجعل الإنصاتَ لكلامِ الله ثم اتّباعَه دأبك."}},{"n":19,"reflection":{"text":"«ثم إن علينا بيانه»: ثم إنّ علينا، بعد حفظه وقراءته، بيانَ معانيه وتفسيرَه وإيضاحَ أحكامه لك؛ ففي هذا بيانُ تكفّلِ الله ببيانِ القرآنِ وتفسيره؛ فثِق بأنّ الله يبيّن لك مرادَه، واطلب البيانَ منه، فبيانُ القرآنِ على الله، فتلقَّه واطلب فهمه منه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ الله يبيّن مرادَه، وطلبُ فهمِ القرآنِ منه."},"action":{"text":"تأمّل ضمانَ البيان: ثم إنّ علينا بيانه، أي ثم إنّ علينا بعد جمعه في صدرك وإثباتِ قراءته أن نبيّن لك معانيه ونوضّح لك أحكامه وحلاله وحرامه وتفسيره، فلا يخفى عليك مرادُه «ثم إن علينا بيانه»؛ ففي هذا بيانُ أنّ الله تكفّل لنبيّه ﷺ ببيانِ القرآنِ وتفسيرِ معانيه وإيضاحِ أحكامه، فحفظُه وقراءتُه وبيانُه كلُّها بضمانِ الله؛ فالله متكفّلٌ ببيانِ مرادِه من كلامه؛ فثِق أنت بأنّ الله يبيّن مرادَه لمن أقبل على كلامه بصدقٍ وتدبّر، واطلب فهمَ القرآنِ منه سبحانه بالدعاءِ والتدبّرِ وسؤالِ أهلِ العلم؛ وأنزلنا إليك الذكرَ لتبيّن للناسِ ما نُزِّل إليهم؛ بل هو آياتٌ بيّناتٌ في صدورِ الذين أوتوا العلم؛ ونزّلنا عليك الكتابَ تبيانًا لكلِّ شيء؛ فبيانُ القرآنِ على الله، فمن أقبل على كلامه أعانه على فهمه؛ فتلقَّه، وتدبّره، واطلب البيانَ منه؛ فمن طلب فهمَ القرآنِ من الله أعانه، ومن أعرض حُرِم؛ فاجعل الثقةَ بأنّ الله يبيّن مرادَه وطلبَ فهمِ القرآنِ منه دأبك."}},{"n":20,"reflection":{"text":"«كلا بل تحبون العاجلة»: حقًّا، بل أنتم، أيها الناسُ، تحبّون الدنيا العاجلةَ وتؤثرونها؛ ففي هذا بيانُ أنّ حبَّ الدنيا أصلُ إيثارِ العاجلةِ على الآخرة؛ فاحذر أن يستولي حبُّ الدنيا على قلبك فيُنسيك الآخرة، فحبُّ العاجلةِ أصلُ الغفلة، فآثِر الآخرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من حبِّ الدنيا العاجلة، وإيثارُ الآخرة."},"action":{"text":"تأمّل أصلَ الغفلة: كلّا، أي حقًّا، ردعًا عن حالِ المكذّبين، بل تحبّون العاجلةَ، أي بل أنتم، أيها الناسُ، تحبّون الحياةَ الدنيا العاجلةَ وتؤثرونها وتسعون لها، وهذا هو الحاملُ لكم على تكذيبِ البعثِ والغفلةِ عن الآخرة «كلا بل تحبون العاجلة»؛ ففي هذا بيانُ أنّ حبَّ الدنيا العاجلةِ وإيثارَها أصلُ الغفلةِ عن الآخرةِ وسببُ التكذيبِ والتفريط؛ فحبُّ العاجلةِ رأسُ كلِّ خطيئةٍ وأصلُ الإعراض؛ فاحذر أنت أن يستولي حبُّ الدنيا على قلبك فيُؤثِرها على الآخرةِ ويُنسِيك الاستعدادَ لها، واجعل الدنيا في يدك لا في قلبك، وآثِر الآخرةَ الباقيةَ على العاجلةِ الفانية؛ بل تؤثرون الحياةَ الدنيا والآخرةُ خيرٌ وأبقى؛ من كان يريد العاجلةَ عجّلنا له فيها ما نشاء؛ اعلموا أنما الحياةُ الدنيا لعبٌ ولهو؛ فحبُّ العاجلةِ يحمل على الغفلةِ والتكذيب، وإيثارُ الآخرةِ يحمل على الاستعدادِ والعمل؛ فاحذر حبَّ الدنيا، وآثِر الآخرة، ولا تجعل الدنيا أكبرَ همّك؛ فمن آثر الآخرةَ سعد، ومن آثر العاجلةَ خسر؛ فاجعل الحذرَ من حبِّ الدنيا وإيثارَ الآخرةِ دأبك."}}]},{"title":"انقسامُ الوجوهِ ومشهدُ الاحتضار","range":[21,30],"theme":"تركُ الآخرة «وتذرون الآخرة»، وانقسامُ الوجوه: «وجوه يومئذ ناضرة إلى ربها ناظرة» و«وجوه يومئذ باسرة تظن أن يفعل بها فاقرة»، ومشهدُ الاحتضار «كلا إذا بلغت التراقي وقيل من راق وظن أنه الفراق والتفت الساق بالساق إلى ربك يومئذ المساق»","verses":[{"n":21,"reflection":{"text":"«وتذرون الآخرة»، وتتركون الآخرةَ فلا تعملون لها ولا تهتمّون بها؛ ففي هذا بيانُ أنّ إيثارَ الدنيا يستلزم تركَ العملِ للآخرة؛ فلا تذر الآخرةَ وأنت تعمل للدنيا، بل اعمل لها، فتركُ العملِ للآخرةِ خسران، فاعمل لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للآخرةِ وعدمُ الغفلةِ عنها."},"action":{"text":"تأمّل ذمَّ تركِ الآخرة: وتذرون الآخرةَ، أي وتتركون الآخرةَ خلف ظهوركم فلا تعملون لها ولا تستعدّون لها ولا تهتمّون بأمرها، انشغالًا بالدنيا العاجلةِ التي أحببتموها؛ فجمعتم بين حبِّ الدنيا وتركِ الآخرة «وتذرون الآخرة»؛ ففي هذا بيانُ أنّ إيثارَ الدنيا العاجلةِ يستلزم تركَ العملِ للآخرةِ والغفلةَ عنها، وذلك خسرانٌ مبين، إذ يترك الباقيَ للفاني؛ فتركُ العملِ للآخرةِ مع حبِّ الدنيا سبيلُ الخسران؛ فلا تذر أنت الآخرةَ ولا تغفل عنها وأنت منشغلٌ بالدنيا، بل اعمل لها واجعلها أكبرَ همّك، فإنها الباقية؛ وما هذه الحياةُ الدنيا إلا لهوٌ ولعبٌ وإنّ الدارَ الآخرةَ لهي الحيوان؛ من كان يريد حرثَ الآخرةِ نزد له في حرثه؛ وابتغِ فيما آتاك الله الدارَ الآخرة؛ فالعملُ للآخرةِ نجاة، وتركها خسران؛ فاعمل لها، ولا تغفل عنها، واجعلها همّك الأكبر؛ فمن عمل للآخرةِ ربح، ومن تركها للدنيا خسر؛ فاجعل العملَ للآخرةِ وعدمَ الغفلةِ عنها دأبك."}},{"n":22,"reflection":{"text":"«وجوه يومئذ ناضرة»، وجوهُ المؤمنين يومئذٍ ناضرةٌ حسنةٌ مشرقةٌ بالنعيمِ والسرور؛ ففي هذا بيانُ نضارةِ وجوهِ أهلِ السعادةِ يومَ القيامة؛ فاعمل لتكون وجهك من الناضرةِ المشرقة، فنضارةُ الوجهِ يومئذٍ ثمرةُ الإيمانِ والعمل، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ نضارةِ الوجهِ يومَ القيامةِ بالإيمانِ والعمل."},"action":{"text":"تأمّل نضارةَ وجوهِ السعداء: وجوهٌ يومئذٍ، أي يومَ القيامةِ، ناضرةٌ، أي حسنةٌ بهيّةٌ مشرقةٌ ناعمةٌ مسرورة، قد علاها النورُ والبهجةُ والحسنُ من أثرِ النعيمِ وسرورِ لقاءِ الله؛ وهي وجوهُ المؤمنين السعداء «وجوه يومئذ ناضرة»؛ ففي هذا بيانُ حالِ وجوهِ أهلِ السعادةِ يومَ القيامة: نضارةٌ وإشراقٌ وحسنٌ وسرور، جزاءَ إيمانهم وعملهم وإيثارهم الآخرة؛ فنضارةُ الوجهِ يومئذٍ ثمرةُ الإيمانِ والعملِ الصالح؛ فاعمل أنت لتكون وجهك من الوجوهِ الناضرةِ المشرقةِ يومَ القيامة، بالإيمانِ والعملِ الصالحِ وإيثارِ الآخرة؛ وجوهٌ يومئذٍ مسفرةٌ ضاحكةٌ مستبشرة؛ تعرف في وجوههم نضرةَ النعيم؛ للذين أحسنوا الحسنى وزيادة؛ فنضارةُ الوجوهِ يومَ القيامةِ لأهلِ الإيمانِ والعمل؛ فاعمل لها، وآثِر الآخرة، وأحسِن؛ فمن آمن وأحسن نضر وجهه، ومن كفر وأساء اسودّ وجهه؛ فاجعل طلبَ نضارةِ الوجهِ يومَ القيامةِ بالعملِ دأبك."}},{"n":23,"reflection":{"text":"«إلى ربها ناظرة»: تنظر إلى ربّها سبحانه (رؤيةُ المؤمنين لربّهم في الجنّة، أعظمُ نعيمها)؛ ففي هذا بيانُ أعظمِ نعيمِ الجنّة: النظرِ إلى وجهِ الله الكريم؛ فاعمل لتنال شرفَ النظرِ إلى ربّك، فرؤيةُ الله أعظمُ النعيم، فاطلبها بعملك وإخلاصك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ أعظمِ النعيم: النظرِ إلى وجهِ الله، بالإيمانِ والإخلاص."},"action":{"text":"تأمّل أعظمَ النعيم: إلى ربّها ناظرةٌ، أي تنظر تلك الوجوهُ الناضرةُ إلى ربّها سبحانه عِيانًا في الجنّة، تراه بأبصارها كما ترى القمرَ ليلةَ البدر؛ وهذه رؤيةُ المؤمنين لربّهم، وهي أعلى نعيمِ الجنّةِ وأجلُّه، أثبتها أهلُ السنّةِ حقًّا بلا تكييفٍ ولا تشبيه «إلى ربها ناظرة»؛ ففي هذا بيانُ أعظمِ نعيمِ أهلِ الجنّة: النظرِ إلى وجهِ ربّهم الكريمِ ورؤيتِه سبحانه، وهو نعيمٌ يفوق كلَّ نعيمِ الجنّة؛ فرؤيةُ الله أعظمُ ما يُنال في الجنّة؛ فاعمل أنت لتنال شرفَ النظرِ إلى وجهِ ربّك، بالإيمانِ والإخلاصِ والعملِ الصالح، واسأل الله لذّةَ النظرِ إلى وجهه؛ للذين أحسنوا الحسنى وزيادة (الزيادةُ: النظرُ إلى وجهِ الله كما فسّرها النبيُّ ﷺ)؛ إنكم سترون ربّكم كما ترون القمرَ ليلةَ البدرِ لا تُضامّون في رؤيته؛ وجوهٌ يومئذٍ ناضرة إلى ربّها ناظرة؛ فالنظرُ إلى وجهِ الله أعلى النعيمِ وغايةُ ما يُطلَب؛ فاعمل له، وأخلِص، واسأل الله إيّاه؛ فمن آمن وأحسن نال شرفَ النظرِ إلى ربّه، ومن كفر حُجِب عنه؛ فاجعل طلبَ النظرِ إلى وجهِ الله بالإيمانِ والإخلاصِ دأبك."}},{"n":24,"reflection":{"text":"«ووجوه يومئذ باسرة»، ووجوهُ الكفّارِ يومئذٍ عابسةٌ كالحةٌ شديدةُ الكراهيةِ والعبوس؛ ففي هذا بيانُ حالِ وجوهِ أهلِ الشقاءِ يومَ القيامة؛ فاحذر أن يكون وجهك من الباسرةِ الكالحة، فبسورُ الوجهِ يومئذٍ ثمرةُ الكفرِ والمعصية، فاتّقِ سببه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من بسورِ الوجهِ يومَ القيامةِ باتّقاءِ الكفرِ والمعصية."},"action":{"text":"تأمّل بسورَ وجوهِ الأشقياء: ووجوهٌ يومئذٍ، أي يومَ القيامةِ، باسرةٌ، أي كالحةٌ عابسةٌ شديدةُ العبوسِ والتكرّهِ والسوادِ والغمّ، قد علاها الحزنُ والكآبةُ لِما ترى من العذاب؛ وهي وجوهُ الكفّارِ والأشقياء «ووجوه يومئذ باسرة»؛ ففي هذا بيانُ حالِ وجوهِ أهلِ الشقاءِ يومَ القيامة: عبوسٌ وكلوحٌ وسوادٌ وكآبة، جزاءَ كفرهم ومعاصيهم وإيثارهم الدنيا؛ فبسورُ الوجهِ يومئذٍ ثمرةُ الكفرِ والمعصية؛ فاحذر أنت أن يكون وجهك من الوجوهِ الباسرةِ الكالحةِ يومَ القيامة، باتّقاءِ الكفرِ والمعاصي والإقبالِ على الإيمانِ والعمل؛ ووجوهٌ يومئذٍ عليها غبرةٌ ترهقها قترة؛ يوم تبيضّ وجوهٌ وتسودّ وجوه؛ خاشعةً أبصارهم ترهقهم ذلّة؛ فبسورُ الوجوهِ يومَ القيامةِ لأهلِ الكفرِ والمعصية؛ فاتّقِ سببه، وآمن، واعمل؛ فمن آمن وأحسن نضر وجهه، ومن كفر وأساء بسر وجهه؛ فاجعل الحذرَ من بسورِ الوجهِ باتّقاءِ الكفرِ والمعصيةِ دأبك."}},{"n":25,"reflection":{"text":"«تظن أن يفعل بها فاقرة»: توقن (أو تظنّ) أنه يُفعَل بها داهيةٌ عظيمةٌ تقصم الظهر؛ ففي هذا بيانُ خوفِ أهلِ الشقاءِ من العذابِ الفادحِ يومَ القيامة؛ فاعمل لتأمن الفاقرةَ يومَ القيامة، فخوفُ الفاقرةِ حالُ من فرّط، فاعمل لتأمن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للأمنِ من عذابِ القيامة، والحذرُ من الفاقرة."},"action":{"text":"تأمّل خوفَ الأشقياء: تظنّ، أي توقن تلك الوجوهُ الباسرة، أو تتوقّع وتعلم، أن يُفعَل بها فاقرةٌ، أي داهيةٌ عظيمةٌ ومصيبةٌ فادحةٌ تكسر فقارَ الظهرِ من شدّتها، وهي العذابُ الأليم؛ فهي في خوفٍ ويقينٍ بنزولِ العذابِ بها «تظن أن يفعل بها فاقرة»؛ ففي هذا بيانُ حالِ أهلِ الشقاءِ يومَ القيامة: خوفٌ ويقينٌ بنزولِ الداهيةِ العظمى والعذابِ الفادحِ الذي يقصم الظهر، جزاءَ كفرهم وتفريطهم؛ فخوفُ الفاقرةِ يومئذٍ حالُ من فرّط وأعرض؛ فاعمل أنت لتأمن الفاقرةَ والعذابَ يومَ القيامة، بالإيمانِ والتقوى والعملِ الصالحِ والتوبة، ولا تكن ممّن يخاف الداهيةَ لتفريطه؛ يعلمون أنه يُفعَل بهم فاقرة؛ وترى المجرمين يومئذٍ مقرّنين في الأصفاد؛ يوم لا يُغني مولًى عن مولًى شيئًا؛ فالفاقرةُ عذابُ من فرّط، والأمنُ منها بالعملِ الصالح؛ فاعمل لتأمن، وآمن، وتب؛ فمن عمل صالحًا أمِن، ومن فرّط خاف الفاقرة؛ فاجعل العملَ للأمنِ من عذابِ القيامةِ دأبك."}},{"n":26,"reflection":{"text":"«كلا إذا بلغت التراقي»: حقًّا، إذا بلغت الروحُ التراقيَ (عظامَ أعلى الصدرِ عند الحلقوم) في سياقِ الموت؛ ففي هذا بيانُ مشهدِ الاحتضارِ وقربِ مفارقةِ الروح؛ فتذكّر لحظةَ بلوغِ الروحِ التراقيَ فاستعدّ لها قبل فواتها، فالاحتضارُ لحظةُ الحقيقة، فبادر قبله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ لحظةِ الاحتضارِ والاستعدادُ لها قبل فواتها."},"action":{"text":"تأمّل مشهدَ الاحتضار: كلّا، أي حقًّا، ردعًا عن حبِّ الدنيا وتركِ الآخرة، إذا بلغت التراقيَ، أي إذا بلغت الروحُ التراقيَ (وهي العظامُ المكتنفةُ لثغرةِ النحرِ أعلى الصدر) عند خروجها في سياقِ الموتِ والاحتضار، فقربت مفارقتُها للبدن «كلا إذا بلغت التراقي»؛ ففي هذا بيانُ مشهدِ الاحتضارِ وبلوغِ الروحِ التراقيَ عند الموت، وهي لحظةُ الحقيقةِ التي ينكشف فيها الغطاءُ ويعاين فيها العبدُ مصيره؛ فلحظةُ الاحتضارِ لحظةُ حقٍّ لا مردَّ بعدها؛ فتذكّر أنت لحظةَ بلوغِ روحك التراقيَ، واستعدّ لها بالتوبةِ والإيمانِ والعملِ قبل أن تحضرك فلا ينفع الاستعداد؛ فلولا إذا بلغت الحلقوم * وأنتم حينئذٍ تنظرون؛ حتى إذا جاء أحدهم الموتُ قال ربِّ ارجعون؛ وليست التوبةُ للذين يعملون السيّئاتِ حتى إذا حضر أحدهم الموتُ قال إني تبت الآن؛ فلحظةُ الاحتضارِ نهايةُ مهلةِ العمل، والموفّقُ من استعدّ قبلها؛ فتذكّرها، واستعدّ لها، وبادر بالتوبةِ قبل فواتها؛ فمن استعدّ قبل الاحتضارِ نجا، ومن سوّف حتى بلغت الروحُ التراقيَ ندم؛ فاجعل تذكّرَ لحظةِ الاحتضارِ والاستعدادَ لها دأبك."}},{"n":27,"reflection":{"text":"«وقيل من راق»، وقال من حضره: من يرقيه ويشفيه (طالبين له راقيًا)، أو من يرقى بروحه من الملائكة؛ ففي هذا بيانُ عجزِ الخلقِ عن دفعِ الموتِ عند حضوره؛ فلا تعلّق رجاءك بالخلقِ عند الشدائد، فلا راقيَ يدفع الموت، فتعلّق بالله وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التعلّقُ بالله وحده، والعلمُ بعجزِ الخلقِ عن دفعِ الموت."},"action":{"text":"تأمّل عجزَ الخلق: وقيل من راقٍ، أي قال من حضر المحتضرَ من أهله: هل من راقٍ يرقيه ويطبّه ويشفيه لعلّه يبرأ؟ التماسًا للنجاةِ من كلِّ سبيل، وقد عجزت الأسباب؛ وقيل: تقول الملائكةُ: من يرقى بروحه، أملائكةُ الرحمةِ أم ملائكةُ العذاب؟ «وقيل من راق»؛ ففي هذا بيانُ عجزِ الخلقِ عن دفعِ الموتِ عند حضوره، وأنّ الأسبابَ كلَّها تنقطع عند بلوغِ الروحِ التراقي، فلا راقيَ ولا طبيبَ ولا حبيبَ يدفع؛ فلا يدفع الموتَ عند حضوره أحدٌ من الخلق؛ فلا تعلّق أنت رجاءك بالخلقِ عند الشدائدِ والموت، بل تعلّق بالله وحده، فهو القادرُ على النفعِ والضرّ، والخلقُ عاجزون؛ فلولا إذا بلغت الحلقوم؛ أفرأيتم ما تُمنون؛ نحن قدّرنا بينكم الموت؛ قل لن ينفعكم الفرارُ إن فررتم من الموت؛ فالخلقُ عاجزون عن دفعِ الموت، والتعلّقُ يكون بالله وحده؛ فتعلّق به، ولا ترجُ سواه عند الشدائد؛ فمن تعلّق بالله كُفِي، ومن تعلّق بالخلقِ خُذِل؛ فاجعل التعلّقَ بالله وحده والعلمَ بعجزِ الخلقِ دأبك."}},{"n":28,"reflection":{"text":"«وظن أنه الفراق»، وأيقن المحتضرُ أنه فراقُ الدنيا والأهلِ والمال؛ ففي هذا بيانُ يقينِ المحتضرِ بمفارقةِ الدنيا؛ فاستحضر أنك مفارقٌ للدنيا لا محالة، فاعمل لِما بعد الفراق، فالفراقُ حقٌّ فأعدّ له، فاعمل قبله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ فراقِ الدنيا الحتميِّ والعملُ لِما بعده."},"action":{"text":"تأمّل يقينَ المفارقة: وظنّ، أي أيقن المحتضرُ وعلم علمًا لا شكّ فيه (والظنُّ هنا بمعنى اليقين)، وأنه الفراقُ، أي أنّ ما نزل به هو فراقُ الدنيا والأهلِ والمالِ والولد، ومفارقةُ كلِّ ما ألِفه، فينتقل إلى الآخرة «وظن أنه الفراق»؛ ففي هذا بيانُ أنّ المحتضرَ عند بلوغِ روحه التراقيَ يوقن أنه مفارقٌ للدنيا لا رجعةَ له إليها، فينكشف له الحقُّ الذي كان يغفل عنه؛ فمفارقةُ الدنيا حقٌّ يقينيٌّ لكلِّ حيّ؛ فاستحضر أنت أنك مفارقٌ للدنيا وأهلِها ومالِها لا محالة، فاعمل لِما بعد الفراقِ من الآخرة، ولا تركن إلى ما ستفارقه، وقدّم لدارِ البقاء؛ كلُّ نفسٍ ذائقةُ الموت؛ وما هذه الحياةُ الدنيا إلا متاعُ الغرور؛ ما عندكم ينفد وما عند الله باق؛ فالفراقُ حقٌّ لكلِّ حيّ، والعاقلُ من أعدّ لِما بعده؛ فاستحضره، واعمل لِما بعده، ولا تركن إلى الفاني؛ فمن أعدّ لِما بعد الفراقِ نجا، ومن ركن إلى الدنيا ندم؛ فاجعل استحضارَ فراقِ الدنيا والعملَ لِما بعده دأبك."}},{"n":29,"reflection":{"text":"«والتفت الساق بالساق»، والتفّت ساقُ الميتِ بساقه (من شدّةِ النزع)، أو التفّت شدّةُ الدنيا بشدّةِ الآخرة، أو التفّت آخرُ أيامِ الدنيا بأوّلِ أيامِ الآخرة؛ ففي هذا بيانُ اجتماعِ الشدائدِ على المحتضر؛ فاستعدّ لشدّةِ النزعِ بالعملِ الصالح، فشدائدُ الموتِ تجتمع فأعدّ لها، فاعمل قبلها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ لشدّةِ النزعِ بالعملِ الصالح."},"action":{"text":"تأمّل اجتماعَ الشدائد: والتفّت الساقُ بالساقِ، أي التفّت إحدى ساقَي الميتِ بالأخرى عند خروجِ الروحِ من شدّةِ الكرب، أو ماتت رجلاه فلا تحملانه؛ وقيل: التفّت شدّةُ فراقِ الدنيا بشدّةِ إقبالِ الآخرة، أو التفّ أمرُ الدنيا بأمرِ الآخرة، فاجتمعت الشدائدُ والكروب «والتفت الساق بالساق»؛ ففي هذا بيانُ شدّةِ حالِ المحتضرِ عند النزع، واجتماعِ الكروبِ والشدائدِ عليه: كربِ الموتِ وكربِ فراقِ الدنيا وكربِ إقبالِ الآخرة؛ فشدائدُ الموتِ عظيمةٌ تجتمع على المحتضر؛ فاستعدّ أنت لتلك الشدّةِ بالعملِ الصالحِ والإيمانِ والتوبة، فإنّ الله يُثبِّت المؤمنَ ويُهوِّن عليه، ويشدّد على المفرّط؛ إنّ للموتِ سكرات؛ وجاءت سكرةُ الموتِ بالحقِّ ذلك ما كنت منه تحيد؛ يُثبِّت الله الذين آمنوا بالقولِ الثابتِ في الحياةِ الدنيا وفي الآخرة؛ فشدائدُ النزعِ تجتمع، والاستعدادُ لها بالعملِ الصالحِ الذي يُثبِّت؛ فاستعدّ لها، واعمل، وتب، وأحسِن الظنَّ بالله؛ فمن استعدّ بالعملِ هُوِّنت عليه، ومن فرّط اشتدّت عليه؛ فاجعل الاستعدادَ لشدّةِ النزعِ بالعملِ الصالحِ دأبك."}},{"n":30,"reflection":{"text":"«إلى ربك يومئذ المساق»: إلى ربّك وحده يومئذٍ المرجعُ والمصيرُ تُساق إليه الأرواحُ والخلائقُ للحساب؛ ففي هذا بيانُ أنّ مساقَ الخلقِ ومصيرهم إلى الله؛ فاستحضر أنّ مساقك إلى الله، فاعمل لِما تُساق إليه، فالمساقُ إلى ربّك فأعدّ للقائه، فاعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ المساقِ إلى الله والعملُ للقائه."},"action":{"text":"تأمّل المساقَ إلى الله: إلى ربّك يومئذٍ المساقُ، أي إلى ربّك وحده يومئذٍ (يومَ الاحتضارِ أو يومَ القيامة) مرجعُ العبدِ ومصيره، تُساق روحه ثم يُساق يومَ القيامةِ إلى موقفِ الحسابِ والجزاء، فلا مساقَ ولا مرجعَ إلا إليه «إلى ربك يومئذ المساق»؛ ففي هذا بيانُ أنّ مصيرَ العبادِ ومساقهم بعد الموتِ وفي القيامةِ إلى الله وحده، إليه تُساق الأرواحُ والأجسادُ للحسابِ والجزاء؛ فالمساقُ إلى الله، والمصيرُ إليه؛ فاستحضر أنت أنّ مساقك ومصيرك إلى الله، واعمل لِما تُساق إليه، وأعدّ للقاءِ ربّك ما يُنجيك؛ وأنّ إلى ربّك المنتهى؛ يا أيها الإنسانُ إنك كادحٌ إلى ربّك كدحًا فملاقيه؛ وسيق الذين اتّقوا ربّهم إلى الجنّةِ زمرًا؛ فالمساقُ إلى الله، والعاقلُ من أعدّ للقائه؛ فاستحضره، واعمل للقائه، وأعدّ العدّة؛ فمن أعدّ للقاءِ الله نجا، ومن غفل عن مساقه خسر؛ فاجعل استحضارَ المساقِ إلى الله والعملَ للقائه دأبك."}}]},{"title":"ذمُّ المكذّبِ المتكبّرِ والبرهانُ على البعث","range":[31,40],"theme":"ذمُّ من كذّب وتولّى «فلا صدق ولا صلى ولكن كذب وتولى ثم ذهب إلى أهله يتمطى»، والوعيدُ «أولى لك فأولى ثم أولى لك فأولى»، وإبطالُ ظنِّ الإهمال «أيحسب الإنسان أن يترك سدى»، والبرهانُ على البعثِ من الخلقِ الأوّل «ألم يك نطفة من مني يمنى... فجعل منه الزوجين الذكر والأنثى أليس ذلك بقادر على أن يحيي الموتى»","verses":[{"n":31,"reflection":{"text":"«فلا صدق ولا صلى»: فلا صدّق هذا المكذّبُ بالحقِّ ولا صلّى لربّه؛ ففي هذا بيانُ ذمِّ من جمع بين تركِ التصديقِ وتركِ الصلاة؛ فاجمع بين تصديقِ الحقِّ والصلاةِ لربّك، فتركُهما جماعُ الشرّ، فصدّق وصلِّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين تصديقِ الحقِّ والصلاةِ لله."},"action":{"text":"تأمّل ذمَّ المكذّب: فلا صدّق، أي فلا صدّق هذا الإنسانُ (المكذّبُ، وقيل نزلت في أبي جهل) بالله ورسولِه والحقّ، ولا آمن بقلبه، ولا صلّى، أي ولا أدّى الصلاةَ لربّه ولا عبده ببدنه؛ فجمع بين تكذيبِ القلبِ وتركِ العملِ «فلا صدق ولا صلى»؛ ففي هذا بيانُ ذمِّ من جمع بين تركِ التصديقِ (وهو عملُ القلب) وتركِ الصلاة (وهي أعظمُ أعمالِ الجوارح)، فخلا من الإيمانِ والعمل؛ فتركُ التصديقِ والصلاةِ جماعُ الشرِّ والخسران؛ فاجمع أنت بين تصديقِ الحقِّ بقلبك والصلاةِ لربّك ببدنك، فإنّ الإيمانَ تصديقٌ وعمل؛ ولكنْ كذّب وتولّى؛ فويلٌ للمصلّين الذين هم عن صلاتهم ساهون؛ قد أفلح من تزكّى وذكر اسمَ ربّه فصلّى؛ فالتصديقُ والصلاةُ جماعُ الخير، وتركُهما جماعُ الشرّ؛ فصدّق، وصلِّ، واجمع بين إيمانِ القلبِ وعملِ الجوارح؛ فمن صدّق وصلّى أفلح، ومن كذّب وترك الصلاةَ خسر؛ فاجعل الجمعَ بين تصديقِ الحقِّ والصلاةِ لله دأبك."}},{"n":32,"reflection":{"text":"«ولكن كذب وتولى»، ولكنْ كذّب بالحقِّ وتولّى وأعرض عن الطاعة؛ ففي هذا بيانُ أنّ التكذيبَ والإعراضَ ضدُّ التصديقِ والعمل؛ فاحذر التكذيبَ والتولّي، بل صدّق وأقبِل، فالتكذيبُ والإعراضُ سبيلُ الهلاك، فأقبِل على الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على الحقِّ وتصديقُه، والحذرُ من التكذيبِ والإعراض."},"action":{"text":"تأمّل ضدَّ الإيمان: ولكنْ كذّب، أي بدل أن يصدّق كذّب بالحقِّ وبالرسولِ وبالقرآن، وتولّى، أي بدل أن يصلّيَ ويطيع تولّى وأعرض عن الإيمانِ والطاعةِ وأدبر «ولكن كذب وتولى»؛ ففي هذا بيانُ أنّ هذا الإنسانَ جمع بين ضدّي الإيمانِ والعمل: كذّب بقلبه (ضدَّ التصديق)، وتولّى ببدنه (ضدَّ الصلاةِ والطاعة)، فاستحقّ الوعيد؛ فالتكذيبُ والإعراضُ سبيلُ الهلاكِ والخسران؛ فاحذر أنت التكذيبَ بالحقِّ والإعراضَ عن الطاعة، بل أقبل على الحقِّ مصدّقًا وعلى الطاعةِ منقادًا؛ فكذّبوه فعقروها فدمدم عليهم ربّهم؛ الذي كذّب وتولّى؛ فأمّا من طغى وآثر الحياةَ الدنيا فإنّ الجحيمَ هي المأوى؛ فالتكذيبُ والتولّي جماعُ الشقاء، والتصديقُ والإقبالُ جماعُ السعادة؛ فأقبل على الحقّ، وصدّق، ولا تعرض؛ فمن صدّق وأقبل سعد، ومن كذّب وتولّى هلك؛ فاجعل الإقبالَ على الحقِّ والحذرَ من التكذيبِ والإعراضِ دأبك."}},{"n":33,"reflection":{"text":"«ثم ذهب إلى أهله يتمطى»: ثم ذهب إلى أهله يتبختر مسرورًا معجبًا بنفسه (بلا مبالاةٍ بما فرّط)؛ ففي هذا بيانُ ذمِّ الكبرِ والاختيالِ والغفلةِ بعد المعصية؛ فاحذر الكبرَ والتبختر والفرحَ بالمعصية، فالاختيالُ مع التفريطِ جمعٌ بين ذنبين، فتواضع وحاسب نفسك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكبرِ والاختيالِ والغفلةِ بعد التفريط، والتواضعُ والمحاسبة."},"action":{"text":"تأمّل كبرَه وغفلته: ثم ذهب إلى أهله، أي بعد تكذيبه وتولّيه انصرف إلى أهله، يتمطّى، أي يتبختر في مشيته ويتبخترُ متكبّرًا معجبًا بنفسه مسرورًا، لا يبالي بما فرّط فيه من حقِّ الله؛ فجمع إلى التكذيبِ والإعراضِ الكبرَ والاختيالَ والغفلة «ثم ذهب إلى أهله يتمطى»؛ ففي هذا بيانُ ذمِّ من يكذّب ويعرض ثم يتبختر مسرورًا معجبًا بنفسه غيرَ مبالٍ بتفريطه، فجمع بين المعصيةِ والكبرِ والغفلةِ عن العاقبة؛ فالكبرُ والاختيالُ مع التفريطِ جماعُ سوءٍ يُضاعِف الوعيد؛ فاحذر أنت الكبرَ والتبختر والإعجابَ بالنفسِ والفرحَ بعد المعصية، وتواضع لله، وحاسب نفسك، ولا تغترّ؛ ولا تمشِ في الأرضِ مرحًا؛ فرح بما عنده من العلم؛ ذلكم بما كنتم تفرحون في الأرضِ بغيرِ الحقِّ وبما كنتم تمرحون؛ فالكبرُ والاختيالُ والغفلةُ بعد التفريطِ سبيلُ الوعيد، والتواضعُ والمحاسبةُ سبيلُ النجاة؛ فتواضع، وحاسب نفسك، ولا تغترّ؛ فمن تواضع وحاسب نفسه نجا، ومن تكبّر واغترّ هلك؛ فاجعل الحذرَ من الكبرِ والاختيالِ والتواضعَ والمحاسبةَ دأبك."}},{"n":34,"reflection":{"text":"«أولى لك فأولى»، وليَك المكروهُ وقرُب منك العذابُ (تهديدٌ ووعيدٌ متكرّر)؛ ففي هذا بيانُ تهديدِ المكذّبِ المتكبّرِ بالوعيد؛ فاحذر أن يحقّ عليك الوعيدُ بتكذيبك وكبرك، فالوعيدُ يتربّص بالمكذّب، فاتّقِ سببه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من وعيدِ الله باتّقاءِ التكذيبِ والكبر."},"action":{"text":"تأمّل الوعيدَ: أولى لك فأولى، أي وليَك المكروهُ وقرُب منك الهلاكُ والعذابُ ووليَك، تهديدٌ ووعيدٌ للمكذّبِ المتكبّر (وقد قالها النبيُّ ﷺ لأبي جهلٍ آخذًا بيده)؛ فكُرِّر الوعيدُ تغليظًا: أولى لك فأولى، أي الويلُ والهلاكُ أولى بك «أولى لك فأولى»؛ ففي هذا بيانُ تهديدِ الله للمكذّبِ المتكبّرِ ووعيدِه بأنّ العذابَ والهلاكَ قريبٌ منه أولى به؛ فالوعيدُ يتربّص بالمكذّبِ المعرض؛ فاحذر أنت أن يحقّ عليك وعيدُ الله بتكذيبك أو إعراضك أو كبرك، واتّقِ أسبابَ الوعيدِ بالإيمانِ والعملِ والتواضع؛ فأولى لهم طاعةٌ وقولٌ معروف؛ ويلٌ لكلِّ همزةٍ لمزة؛ فالوعيدُ لاحقٌ بالمكذّبِ المتكبّر، والنجاةُ باتّقاءِ سببه؛ فاتّقِ التكذيبَ والكبر، وآمن، واعمل؛ فمن اتّقى الوعيدَ بالعملِ نجا، ومن كذّب واستكبر حقّ عليه؛ فاجعل الحذرَ من وعيدِ الله باتّقاءِ التكذيبِ والكبرِ دأبك."}},{"n":35,"reflection":{"text":"«ثم أولى لك فأولى»: ثم قرُب منك المكروهُ والعذابُ (تكرارٌ للوعيدِ تأكيدًا)؛ ففي هذا تكريرُ الوعيدِ تأكيدًا لعظمِ جرمِ المكذّبِ المتكبّر؛ فاستشعر عظمَ خطرِ التكذيبِ والكبرِ الذي تكرّر فيه الوعيد، فتكريرُ الوعيدِ لتكريرِ الحذر، فاحذر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استشعارُ عظمِ خطرِ التكذيبِ والكبرِ الذي تكرّر فيه الوعيد."},"action":{"text":"تأمّل تكريرَ الوعيد: ثم أولى لك فأولى، أي ثم قرُب منك المكروهُ والعذابُ ووليَك، كُرِّر الوعيدُ مرّةً ثانيةً تأكيدًا وتغليظًا وتهديدًا بعد تهديد، لعظمِ جرمِ المكذّبِ المتكبّرِ المعرض «ثم أولى لك فأولى»؛ ففي هذا بيانُ تكريرِ الوعيدِ للمكذّبِ المتكبّر، تأكيدًا لعظمِ جرمه واستحقاقِه للعذاب، ومبالغةً في التهديد؛ فتكريرُ الوعيدِ إشعارٌ بعظمِ الخطرِ وشدّةِ الحذرِ المطلوب؛ فاستشعر أنت عظمَ خطرِ التكذيبِ والإعراضِ والكبرِ الذي تكرّر فيه وعيدُ الله، واحذره غايةَ الحذر، وأقبل على الإيمانِ والطاعةِ والتواضع؛ فبأيِّ آلاءِ ربّكما تكذّبان (كُرِّرت للتأكيد)؛ ويلٌ يومئذٍ للمكذّبين (كُرِّرت)؛ كلّا سوف تعلمون ثم كلّا سوف تعلمون؛ فتكريرُ الوعيدِ لتعظيمِ الخطرِ وتأكيدِ الحذر؛ فاحذر، واستشعر عظمَ الخطر، وأقبل على الحقّ؛ فمن حذر الوعيدَ واتّعظ نجا، ومن أصرّ حقّ عليه؛ فاجعل استشعارَ عظمِ خطرِ التكذيبِ والكبرِ دأبك."}},{"n":36,"reflection":{"text":"«أيحسب الإنسان أن يترك سدى»: أيظنّ الإنسانُ أن يُترَك مهملًا لا يُؤمَر ولا يُنهى ولا يُبعَث ولا يُحاسَب؟ ففي هذا بيانُ إبطالِ ظنِّ الإهمالِ وإثباتِ التكليفِ والبعث؛ فاعلم أنك لم تُخلَق عبثًا ولن تُترَك سدًى، فأنت مكلّفٌ محاسَب، فاعمل لحسابك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ أنّ الإنسانَ مكلّفٌ محاسَبٌ لم يُخلَق عبثًا."},"action":{"text":"تأمّل إبطالَ ظنِّ الإهمال: أيحسب الإنسانُ، أي أيظنّ الإنسانُ المكذّبُ، أن يُترَك سدًى، أي مهملًا هملًا، لا يُؤمَر ولا يُنهى في الدنيا، ولا يُبعَث ولا يُحاسَب ولا يُجازى في الآخرة؟ استفهامُ إنكارٍ، أي لا يُترَك كذلك، بل هو مأمورٌ منهيٌّ مبعوثٌ محاسَب «أيحسب الإنسان أن يترك سدى»؛ ففي هذا بيانُ إبطالِ ظنِّ من يظنّ أنه خُلِق عبثًا وسيُترَك مهملًا بلا تكليفٍ ولا بعثٍ ولا حساب، وإثباتِ أنّ الله خلقه لحكمةٍ وكلّفه وسيبعثه ويحاسبه؛ فالإنسانُ مخلوقٌ لحكمةٍ مكلّفٌ محاسَبٌ لا مهمَل؛ فاستحضر أنت أنك لم تُخلَق عبثًا ولن تُترَك سدًى، بل أنت مأمورٌ منهيٌّ ستُبعَث وتُحاسَب، فاعمل لحسابك واستعدّ ليومِ لقائك؛ أفحسبتم أنما خلقناكم عبثًا وأنكم إلينا لا تُرجَعون؛ وما خلقنا السماءَ والأرضَ وما بينهما لاعبين؛ أيحسب أن لن يقدر عليه أحد؛ فالإنسانُ مكلّفٌ محاسَبٌ مخلوقٌ لحكمة، لا مهمَلٌ ولا متروك؛ فاستحضر ذلك، واعمل، واستعدّ للحساب؛ فمن علم أنه محاسَبٌ عمل، ومن ظنّ الإهمالَ ضاع؛ فاجعل استحضارَ أنك مكلّفٌ محاسَبٌ دأبك."}},{"n":37,"reflection":{"text":"«ألم يك نطفة من مني يمنى»: ألم يكن هذا الإنسانُ نطفةً من منيٍّ يُصَبّ في الرحم؟ ففي هذا بيانُ ضعفِ أصلِ الإنسانِ تذكيرًا بقدرةِ الله على بعثه؛ فتأمّل أصلك الضعيفَ لتعلم قدرةَ خالقك على إعادتك، فمن أنشأك من نطفةٍ قادرٌ على بعثك، فأيقن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ بتأمّلِ أصلِ الخلق، واليقينُ بقدرةِ الله على البعث."},"action":{"text":"تأمّل أصلَ الخلق: ألم يك نطفةً من منيٍّ يُمنى، أي ألم يكن هذا الإنسانُ المكذّبُ بالبعثِ في أوّلِ أمره نطفةً حقيرةً من منيٍّ يُصَبُّ ويُراق في الرحم؟ استفهامُ تقريرٍ وتذكيرٍ بأصلِ خلقه الضعيف «ألم يك نطفة من مني يمنى»؛ ففي هذا بيانُ تذكيرِ الإنسانِ بأصلِه الضعيفِ الحقير (نطفةٍ من منيّ)، استدلالًا على قدرةِ الله على بعثه، فمن أنشأه من ذلك الأصلِ الضعيفِ قادرٌ على إعادته؛ فأصلُ الإنسانِ ضعيفٌ يدلّ على قدرةِ خالقه؛ فتأمّل أنت أصلك الضعيفَ (نطفةً مهينة) لتتواضع ولتعلم أنّ من أنشأك منها قادرٌ على إعادتك وبعثك؛ فلينظر الإنسانُ ممّ خُلِق خُلِق من ماءٍ دافق؛ ألم نخلقكم من ماءٍ مهين؛ إنا خلقنا الإنسانَ من نطفةٍ أمشاج؛ فأصلُ الخلقِ الضعيفُ برهانٌ على القدرةِ على البعثِ وداعٍ إلى التواضع؛ فتأمّله، وتواضع، وأيقن بالبعث؛ فمن تأمّل أصله تواضع وأيقن، ومن غفل تكبّر وأنكر؛ فاجعل التواضعَ بتأمّلِ أصلِ الخلقِ واليقينَ بالبعثِ دأبك."}},{"n":38,"reflection":{"text":"«ثم كان علقة فخلق فسوى»: ثم صار النطفةُ علقةً (دمًا جامدًا) فخلقه الله وسوّاه بشرًا سويًّا؛ ففي هذا بيانُ أطوارِ الخلقِ الدالّةِ على قدرةِ الله وحكمته؛ فتأمّل أطوارَ خلقك لتعرف قدرةَ الله عليك، فمن نقلك في الأطوارِ قادرٌ على بعثك، فأيقن واشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ أطوارِ الخلقِ وشكرُ من سوّاك واليقينُ ببعثه."},"action":{"text":"تأمّل أطوارَ الخلق: ثم كان علقةً، أي ثم صارت النطفةُ علقةً، وهي الدمُ الجامدُ الغليظ، فخلق، أي فخلقه الله وقدّره ونقله في أطوارِ الخلق، فسوّى، أي فسوّاه وعدّله بشرًا سويًّا كاملَ الخلقِ والأعضاءِ والحواسّ «ثم كان علقة فخلق فسوى»؛ ففي هذا بيانُ أطوارِ خلقِ الإنسان: من نطفةٍ إلى علقةٍ إلى خلقٍ مسوًّى، وكلُّها تدلّ على كمالِ قدرةِ الله وحكمته، وعلى قدرتِه على البعثِ من بابِ أولى؛ فمن نقل الإنسانَ في الأطوارِ وسوّاه قادرٌ على إعادته؛ فتأمّل أنت أطوارَ خلقك من نطفةٍ فعلقةٍ فخلقٍ سويّ، واعرف بها قدرةَ الله وحكمته، واشكر من سوّاك وعدّلك، وأيقن بقدرته على بعثك؛ خلقكم من نفسٍ واحدة؛ يخلقكم في بطونِ أمّهاتكم خلقًا من بعدِ خلقٍ في ظلماتٍ ثلاث؛ الذي خلقك فسوّاك فعدلك؛ فأطوارُ الخلقِ برهانُ القدرةِ والحكمةِ وموجبُ الشكرِ واليقينِ بالبعث؛ فتأمّلها، واشكر، وأيقن؛ فمن تأمّلها شكر وأيقن، ومن غفل كفر وأنكر؛ فاجعل تأمّلَ أطوارِ الخلقِ وشكرَ من سوّاك دأبك."}},{"n":39,"reflection":{"text":"«فجعل منه الزوجين الذكر والأنثى»: فجعل من الإنسانِ الصنفين: الذكرَ والأنثى؛ ففي هذا بيانُ آيةِ خلقِ الزوجين الدالّةِ على قدرةِ الله وحكمته؛ فتأمّل خلقَ الذكرِ والأنثى من أصلٍ واحدٍ آيةً على قدرةٍ تُحيي الموتى، فمن خلق الزوجين قادرٌ على البعث، فأيقن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ آيةِ خلقِ الزوجين واليقينُ بقدرةِ الله على البعث."},"action":{"text":"تأمّل آيةَ الزوجين: فجعل منه، أي من الإنسانِ (أو من المنيّ)، والزوجين، أي الصنفين، الذكرَ والأنثى، فأوجد الله من جنسِ الإنسانِ ذكرًا وأنثى، ليكون منهما النسلُ والتكاثر، وذلك من عظيمِ قدرته وحكمته «فجعل منه الزوجين الذكر والأنثى»؛ ففي هذا بيانُ آيةِ خلقِ الزوجين (الذكرِ والأنثى) من أصلٍ واحد، وما فيها من الحكمةِ (بقاءِ النسل) والدلالةِ على قدرةِ الله؛ فمن قدر على خلقِ الزوجين من نطفةٍ قادرٌ على إحياءِ الموتى؛ فتأمّل أنت آيةَ خلقِ الذكرِ والأنثى من أصلٍ واحد، واستدلّ بها على قدرةِ الله وحكمته، وعلى قدرته على البعثِ وإحياءِ الموتى؛ ومن آياته أن خلق لكم من أنفسكم أزواجًا؛ وأنه خلق الزوجين الذكرَ والأنثى من نطفةٍ إذا تُمنى؛ يهب لمن يشاء إناثًا ويهب لمن يشاء الذكور؛ فخلقُ الزوجين آيةُ قدرةٍ وحكمةٍ وبرهانٌ على البعث؛ فتأمّلها، واستدلّ بها، وأيقن بالبعث؛ فمن تأمّلها أيقن بقدرةِ الله، ومن غفل أنكر؛ فاجعل تأمّلَ آيةِ خلقِ الزوجين واليقينَ بقدرةِ الله دأبك."}},{"n":40,"reflection":{"text":"«أليس ذلك بقادر على أن يحيي الموتى»: أليس ذلك الذي خلق الإنسانَ من نطفةٍ ونقله في الأطوارِ وخلق الزوجين بقادرٍ على أن يحييَ الموتى؟ بلى؛ ففي هذا بيانُ البرهانِ القاطعِ على البعثِ من الخلقِ الأوّل؛ فأيقن يقينًا جازمًا بقدرةِ الله على إحيائك بعد موتك، فمن قدر على البدء قادرٌ على الإعادة، فأيقن بالبعث.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ الجازمُ بقدرةِ الله على البعثِ استدلالًا بالخلقِ الأوّل."},"action":{"text":"تأمّل خاتمةَ البرهان: أليس ذلك، أي أليس الذي خلق الإنسانَ من نطفةٍ فعلقةٍ فسوّاه وجعل منه الزوجين، بقادرٍ على أن يحييَ الموتى، أي على أن يبعث الخلقَ ويعيدهم أحياءً بعد موتهم؟ استفهامُ تقريرٍ، جوابُه: بلى، هو قادرٌ على ذلك (وكان النبيُّ ﷺ إذا قرأها قال: سبحانك فبلى) «أليس ذلك بقادر على أن يحيي الموتى»؛ ففي هذا بيانُ البرهانِ القاطعِ على البعثِ: أنّ الذي بدأ خلقَ الإنسانِ من نطفةٍ ونقله في الأطوارِ وخلق منه الزوجين قادرٌ بلا شكٍّ على إعادته وإحيائه بعد موته، فالإعادةُ أهونُ من البدء؛ فمن قدر على الخلقِ الأوّلِ قادرٌ على البعثِ يقينًا؛ فأيقن أنت يقينًا جازمًا بقدرةِ الله على بعثك وإحيائك بعد موتك، واستعدّ للقائه، وقل عند قراءتها: بلى سبحانك؛ وهو الذي يبدأ الخلقَ ثم يعيده وهو أهونُ عليه؛ قل يحييها الذي أنشأها أوّلَ مرّة؛ أوليس الذي خلق السماواتِ والأرضَ بقادرٍ على أن يخلق مثلهم بلى؛ فالخلقُ الأوّلُ برهانٌ قاطعٌ على البعث، فالإقرارُ به لازم؛ فأيقن به، واستعدّ للبعث، وسبّح ربّك؛ فمن أيقن بالبعثِ استعدّ وسعد، ومن أنكره جهلًا خسر؛ فاجعل اليقينَ الجازمَ بقدرةِ الله على البعثِ دأبك."}}]}],"coverage":{"covered":40,"total":40}};
